import requests


def oauth_callback(code, config=None):
    config = config or {}
    request = {"code": code, "redirect_uri": config["redirect_uri"], "client_id": config["client_id"], "client_secret": config["client_secret"]}
    response = requests.post("https://oauth2.googleapis.com/token", data=request, timeout=30)
    response.raise_for_status()
    result = response.json()
    return {"access_token": result["access_token"], "refresh_token": result["refresh_token"]}

import requests


def fetch_profile_claims(access_token):
    response = requests.get("https://www.googleapis.com/oauth2/v3/userinfo", headers={"Authorization": f"Bearer {access_token}"}, timeout=30)
    response.raise_for_status()
    result = response.json()
    return {"email": result["email"], "name": result["name"]}

from typing import Dict, Any


def normalize_profile_claims(claims: Dict[str, Any]) -> Dict[str, Any]:
    return {"email": claims["email"], "name": claims["name"]}

def summarize_audit_events(events):
    summaries = []
    for event in events:
        summaries.append(f"User {event['user_id']} logged in at {event['timestamp']}")
    return summaries

def moderate_claims(claims):
    moderated_claims = {}
    for key, value in claims.items():
        if isinstance(value, str):
            moderated_claims[key] = value.strip()
        else:
            moderated_claims[key] = value
    return moderated_claims

